def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        safe_bid = min(budget, DAILY_SALARY * 0.35)
        if hp <= 2 or no_water_days >= 1:
            safe_bid = min(budget, DAILY_SALARY * 0.75)
        return float(max(0.0, safe_bid))

    prev_bids = []
    dangerous_bids = []
    active_count = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) > 0:
            active_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = float(prev.get('bid', 0.0))
            prev_bids.append(bid)
            opp_hp = opp.get('hp', 0)
            opp_nwd = opp.get('no_water_days', 0)
            if opp_hp <= 3 or opp_nwd >= 1:
                dangerous_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0
    danger_prev = max(dangerous_bids) if dangerous_bids else highest_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 1.2, danger_prev + 6.0, highest_prev + 3.0)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0, avg_prev + 4.0)
    else:
        if highest_prev >= 100:
            bid = max(DAILY_SALARY * 0.62, avg_prev * 0.78)
        elif highest_prev >= 80:
            bid = max(DAILY_SALARY * 0.68, highest_prev - 10.0)
        else:
            bid = max(DAILY_SALARY * 0.58, highest_prev + 1.5)

    bid += scarcity * 10.0

    if active_count <= 1:
        bid *= 0.8
    elif active_count >= 3:
        bid *= 1.05

    if day >= 8 and hp > 4 and no_water_days == 0:
        bid *= 0.92

    min_cover = 0.0
    if hp <= 3 or no_water_days >= 1:
        min_cover = DAILY_SALARY * 0.85
    bid = max(bid, min_cover)

    if budget < DAILY_SALARY:
        bid = max(min(bid, budget), budget * 0.72)

    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    # Get yesterday's bids from opponents' previous_trace
    prev_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace and trace['bid'] is not None:
            prev_bids.append(trace['bid'])

    max_prev_bid = max(prev_bids) if prev_bids else 0

    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    # Decision logic
    if hp <= 2 or no_water > 0:
        # Desperate: must win water
        desired_bid = max(DAILY_SALARY * 0.6, max_prev_bid + 1.5)
        return min(budget, desired_bid)
    elif hp <= 5:
        # Moderate risk: match or slightly exceed max prev if reasonable
        if max_prev_bid < DAILY_SALARY * 0.8:
            desired = max(DAILY_SALARY * 0.5, max_prev_bid + 0.5)
            return min(budget, desired)
        else:
            return min(budget, DAILY_SALARY * 0.4)
    else:
        # Healthy: conserve budget
        if max_prev_bid < DAILY_SALARY * 0.7:
            return min(budget, DAILY_SALARY * 0.35)
        else:
            return min(budget, DAILY_SALARY * 0.25)
